QString ChatPageDXX::call(const QString&t,const JsonDXX&d,std::function<void(const JsonDXX&)>done,const QString&id){auto key=client_.request(t,d,id);if(!key.isEmpty())calls_.insert(key,{t,d,std::move(done),user_});return key;}
MessageModelDXX *ChatPageDXX::model(qint64 id){if(!models_.contains(id))models_[id]=new MessageModelDXX(this);return models_[id];}
MessageModelDXX *ChatPageDXX::currentModel()const{return models_.value(current_,nullptr);}
void ChatPageDXX::setAccount(const QString &u,const QString&s,const QString&display,bool active){bool changed=user_!=u||service_!=s;bool activated=!active_&&active;if(user_!=u){calls_.clear();outgoing_.clear();summaries_.clear();drafts_.clear();unread_.clear();acked_.clear();ackQueue_.clear();ackInFlight_=0;before_.clear();for(auto m:models_)delete m;models_.clear();current_=0;cursors_.clear();}if(current_)drafts_[current_]=input_->toPlainText();user_=u;service_=s;display_=display;active_=active;send_->setEnabled(active&&s!="WEIBO");if(changed){++openGeneration_;current_=0;messages_->setModel(nullptr);input_->clear();renderConversations();}if(active&&s!="WEIBO"&&(changed||activated))refresh();}
void ChatPageDXX::refresh(){if(!active_||service_=="WEIBO"||user_.isEmpty())return;list("0");if(cursors_.contains(user_+"/"+service_))sync();}
void ChatPageDXX::list(const QString &cursor){if(listBusy_)return;listBusy_=true;auto service=service_;if(call("chat.conversation.list",{{"service_type",service.toStdString()},{"limit",50},{"cursor",cursor.toStdString()}},[this,service](const JsonDXX&d){listBusy_=false;if(service!=service_){list("0");return;}for(auto s:d["items"].items()){auto id=s["conversation_id"].integer();s.set("latest_message_id",std::max(s["latest_message_id"].integer(),summaries_.value(id)["latest_message_id"].integer()));summaries_[id]=s;}next_=QString::fromStdString(d["next_cursor"].text());auto key=user_+"/"+service;if(!cursors_.contains(key)){qint64 latest=0;for(auto s:d["items"].items())latest=qMax(latest,qint64(s["latest_message_id"].integer()));cursors_[key]=latest;}renderConversations();}).isEmpty())listBusy_=false;}
void ChatPageDXX::renderConversations(){
 QSignalBlocker blocker(conversations_);conversations_->clear();
 std::vector<qint64> ids;for(auto i=summaries_.begin();i!=summaries_.end();++i)if(i.value()["service_type"].text()==service_.toStdString())ids.push_back(i.key());
 std::sort(ids.begin(),ids.end(),[this](qint64 a,qint64 b){auto latestA=summaries_.value(a)["latest_message_id"].integer(),latestB=summaries_.value(b)["latest_message_id"].integer();return latestA==latestB?a>b:latestA>latestB;});
 for(auto id:ids){auto *item=new QListWidgetItem(QString::fromStdString(summaries_.value(id)["title"].text())+(unread_.value(id)?QStringLiteral(" · 未读 %1").arg(unread_[id]):QString()),conversations_);item->setData(Qt::UserRole,id);if(id==current_)conversations_->setCurrentItem(item);}
}
void ChatPageDXX::select(const JsonDXX&s){auto id=s["conversation_id"].integer();if(!id||s["service_type"].text()!=service_.toStdString())return;if(current_)drafts_[current_]=input_->toPlainText();current_=id;selected_=s;selected_.set("latest_message_id",std::max(s["latest_message_id"].integer(),summaries_.value(id)["latest_message_id"].integer()));summaries_[id]=selected_;unread_[id]=0;title_->setText(QStringLiteral("%1 · %2 · %3").arg(service_,display_,QString::fromStdString(s["title"].text())));messages_->setModel(model(id));input_->setPlainText(drafts_.value(id));send_->setEnabled(active_&&s["can_send"].boolean());renderConversations();history(false);emit conversationOpened(id);}
void ChatPageDXX::openPrivate(const QString&t){if(!active_||service_=="WEIBO")return;auto generation=++openGeneration_;call("chat.private.open",{{"service_type",service_.toStdString()},{"target_display_id",t.toStdString()}},[this,t,generation](const JsonDXX&d){if(generation!=openGeneration_)return;auto s=d;s.set("target_display_id",t.toStdString());select(s);});}
void ChatPageDXX::openGroup(qint64 g,qint64 sub){if(!active_||service_=="WEIBO")return;auto generation=++openGeneration_;JsonDXX d{{"group_pk",g}};if(sub)d.set("subgroup_pk",sub);call("chat.group.open",d,[this,generation](const JsonDXX&s){if(generation==openGeneration_)select(s);});}
void ChatPageDXX::history(bool older){if(!current_||historyBusy_.contains(current_))return;auto conversation=current_;JsonDXX d{{"conversation_id",conversation},{"limit",50}};if(older){if(before_.value(conversation)==-1)return;auto m=model(conversation);qint64 minimum=0;for(auto r:m->messages()){auto id=r["message_id"].integer();if(id>0&&(!minimum||id<minimum))minimum=id;}if(!minimum)return;d.set("before_message_id",minimum);}historyBusy_.insert(conversation);if(call("chat.history.get",d,[this,conversation](const JsonDXX&r){for(auto m:r["items"].items())merge(m,false);before_[conversation]=r["has_more"].boolean()?r["before_cursor"].integer():-1;historyBusy_.remove(conversation);}).isEmpty())historyBusy_.remove(conversation);}
void ChatPageDXX::sync(){if(syncing_)return;auto service=service_;auto key=user_+"/"+service;if(!cursors_.contains(key))return;syncing_=true;if(call("chat.sync",{{"service_type",service.toStdString()},{"after_message_id",cursors_[key]},{"limit",50}},[this,key,service](const JsonDXX&d){syncing_=false;if(service_!=service)return;for(auto m:d["items"].items())merge(m,false);cursors_[key]=d["next_cursor"].integer();if(d["has_more"].boolean()&&service_==service)QTimer::singleShot(0,this,[this]{sync();});}).isEmpty())syncing_=false;}
void ChatPageDXX::merge(const JsonDXX&m,bool notify){if(m["service_type"].text()!=service_.toStdString())return;auto conversation=m["conversation_id"].integer(),id=m["message_id"].integer();if(id<=0)return;bool added=model(conversation)->merge(m);auto request=QString::fromStdString(m["request_id"].text());outgoing_.remove(request);if(!summaries_.contains(conversation)){JsonDXX summary{{"conversation_id",conversation},{"service_type",m["service_type"]},{"title",std::string("会话 ")+std::to_string(conversation)},{"can_send",false}};summaries_[conversation]=summary;list("0");}summaries_[conversation].set("latest_message_id",std::max(id,summaries_[conversation]["latest_message_id"].integer()));if(added){if(notify&&conversation!=current_)unread_[conversation]++;emit messageMerged(id,QString::fromStdString(m["content"].text()));}renderConversations();if(QString::fromStdString(m["sender_display_id"].text())!=display_&&!acked_.contains(id)){acked_.insert(id);ackQueue_.enqueue(id);drainAcks();}}
void ChatPageDXX::sendText(const QString &text){if(!current_||!active_||!selected_["can_send"].boolean())return;if(text.trimmed().isEmpty()||text.toUtf8().size()>4096||text.contains(QChar(0))){status_->setText(QStringLiteral("请输入非空文本，最多4096 UTF-8字节。"));return;}QString id=QUuid::createUuid().toString(QUuid::WithoutBraces);auto kind=selected_["kind"].text();QString type=kind=="PRIVATE"?"chat.private.send":"chat.group.send";JsonDXX d{{"content",text.toStdString()}};if(kind=="PRIVATE"){d.set("service_type",service_.toStdString());d.set("target_display_id",selected_["target_display_id"]);}else{d.set("group_pk",selected_["group_pk"]);if(kind=="SUBGROUP")d.set("subgroup_pk",selected_["subgroup_pk"]);}JsonDXX message{{"conversation_id",current_},{"sender_display_id",display_.toStdString()},{"content",text.toStdString()},{"request_id",id.toStdString()},{"status","pending"}};model(current_)->merge(message);outgoing_[id]={type,d,message,current_};input_->clear();drafts_[current_].clear();if(call(type,d,[this](const JsonDXX&m){merge(m,false);},id).isEmpty())model(current_)->setState(id,"unknown");}
void ChatPageDXX::retry(){auto index=messages_->currentIndex();if(!index.isValid())return;auto id=index.data(Qt::UserRole).toString();if(!outgoing_.contains(id))return;auto o=outgoing_[id];if(call(std::get<0>(o),std::get<1>(o),[this](const JsonDXX&m){merge(m,false);},id).isEmpty()){model(std::get<3>(o))->setState(id,"unknown");return;}model(std::get<3>(o))->setState(id,"pending");}

void ChatPageDXX::drainAcks(){
 if(ackInFlight_||ackQueue_.isEmpty()||!client_.connected()||client_.restoringSession())return;
 const auto id=ackQueue_.dequeue();ackInFlight_=id;
 if(call("chat.message.ack",{{"message_id",id}},[this,id](const JsonDXX&){if(ackInFlight_==id)ackInFlight_=0;drainAcks();}).isEmpty()){ackInFlight_=0;acked_.remove(id);}
}
